/*
 * bench_frames.cpp - GENERATED by tools/generate_bench_frames_cpp.py
 * Bench "lamp killer": live-toggleable healthy-bus status frames replayed
 * to extinguish cluster warning lamps on the bench. Steady-state payloads +
 * periods + (for E2E frames) the per-ID MQB CRC magic tables are DERIVED from
 * the real capture "OFF to start cluster.csv" (lights end OFF). Do not hand-edit;
 * re-run the generator to refresh.
 *
 * Safety: every frame defaults to DISABLED at boot (nothing emitted). The user
 * enables them one at a time from the UI to map which frame clears which lamp.
 */
#include "bench_frames.h"
#include "config.h"
#include "settings.h"
#include "can_handler.h"
#include "serial_proto.h"
#include "vw_mqb.h"   // for MQB_CRC8H2F[] (global, filled by vw_mqb_init)

// ---- Per-ID derived MQB CRC magic tables (from the real capture) ----
static const uint8_t MAGIC_0x394[16] = { 0x47, 0x94, 0x92, 0x6A, 0x67, 0xB5, 0x0D, 0x38, 0xE3, 0x8A, 0x5D, 0xB4, 0x54, 0xAB, 0xAE, 0x27 };

static const uint8_t* magic_for(uint16_t id) {
  switch (id) {
    case 0x394: return MAGIC_0x394;
    default: return nullptr;
  }
}

// Apply 4-bit counter (byte1 low nibble) + recompute CRC into byte0,
// using this module's own magic tables + the global CRC8H2F table.
static void apply_crc(uint16_t id, uint8_t* p, uint8_t len, uint8_t counter) {
  if (len < 2) return;
  p[1] = (uint8_t)((p[1] & 0xF0) | (counter & 0x0F));
  const uint8_t* k = magic_for(id);
  uint8_t crc = 0xFF;
  for (uint8_t i = 1; i < len; i++) crc = MQB_CRC8H2F[crc ^ p[i]];
  if (k) crc = MQB_CRC8H2F[crc ^ k[p[1] & 0x0F]];
  p[0] = (uint8_t)(crc ^ 0xFF);
}

// ---- Candidate frame table (DERIVED) ----
struct BenchFrame {
  uint16_t id; uint16_t period_ms; uint8_t dlc;
  uint8_t  tmpl[8]; bool needs_crc; const char* group; const char* label;
};
// Identified telltales first (sorted), then the rest by period.
static const BenchFrame FRAMES[] = {
  { 0x394, 160, 8, {0xD9, 0x19, 0x00, 0x1A, 0x00, 0x00, 0x00, 0x00}, true, "Voyants identifies", "Shift lock - appuyer sur le frein (cadran km/h)" },  // WBA_03
  { 0x64A, 500, 4, {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}, false, "Voyants identifies", "TPMS (cadran RPM)" },
  { 0x656, 1000, 8, {0x00, 0x30, 0x0A, 0x00, 0x00, 0x00, 0x00, 0x00}, false, "Voyants identifies", "Defaillance direction (cadran RPM)" },
};
static const uint8_t N_FRAMES = sizeof(FRAMES)/sizeof(FRAMES[0]);

static bool     g_enabled[N_FRAMES];
static uint32_t g_last_ms[N_FRAMES];
static uint8_t  g_counter[N_FRAMES];

void bench_frames_init() {
  for (uint8_t i = 0; i < N_FRAMES; i++) { g_enabled[i]=false; g_last_ms[i]=0; g_counter[i]=0; }
}

uint8_t bench_frames_count() { return N_FRAMES; }

uint16_t bench_frames_id(uint8_t idx)        { return idx<N_FRAMES?FRAMES[idx].id:0; }
uint16_t bench_frames_period(uint8_t idx)     { return idx<N_FRAMES?FRAMES[idx].period_ms:0; }
bool     bench_frames_needs_crc(uint8_t idx)  { return idx<N_FRAMES?FRAMES[idx].needs_crc:false; }
const char* bench_frames_group(uint8_t idx)   { return idx<N_FRAMES?FRAMES[idx].group:""; }
const char* bench_frames_label(uint8_t idx)   { return idx<N_FRAMES?FRAMES[idx].label:""; }
bool     bench_frames_enabled(uint8_t idx)    { return idx<N_FRAMES?g_enabled[idx]:false; }

bool bench_frames_set_enabled(uint8_t idx, bool on) {
  if (idx >= N_FRAMES) return false;
  g_enabled[idx] = on;
  return true;
}

void bench_frames_all_off() {
  for (uint8_t i = 0; i < N_FRAMES; i++) g_enabled[i] = false;
}

// Send each ENABLED frame at its period. Call from bench_test_tick() only
// (i.e. bench mode active + tx_enabled). Bus = the configured bench bus.
void bench_frames_tick(uint32_t now) {
  CanChannel ch = (settings_get().bench_test_bus == 1) ? CAN_OBD2 : CAN_CLUSTER;
  for (uint8_t i = 0; i < N_FRAMES; i++) {
    if (!g_enabled[i]) continue;
    if (now - g_last_ms[i] < FRAMES[i].period_ms) continue;
    g_last_ms[i] = now;
    CanFrame f;
    f.id = FRAMES[i].id;
    f.len = FRAMES[i].dlc;
    for (uint8_t b = 0; b < 8; b++) f.data[b] = FRAMES[i].tmpl[b];
    if (FRAMES[i].needs_crc) {
      apply_crc(FRAMES[i].id, f.data, f.len, g_counter[i]);
      g_counter[i] = (uint8_t)((g_counter[i] + 1) & 0x0F);
    }
    if (can_send(ch, f)) serial_proto_report_tx(ch, f);
  }
}
